SELECT * FROM easybuy_order

    is_delete = 0
    AND user_id = #{userId}

        AND serial_number LIKE CONCAT('%', #{serialNumber}, '%')

    AND status = #{status}

        AND create_time >= #{startTime}


        AND create_time <= CONCAT(#{endTime}, ' 23:59:59')


ORDER BY create_time DESC

